param([Parameter(Mandatory=$true)][string]$RunId)
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path; $env:PYTHONPATH=Join-Path $root 'cayenne\scripts'; $py=(Get-Command python -ErrorAction SilentlyContinue); if(-not $py){$py=Get-Command (Join-Path $env:LOCALAPPDATA 'Programs\Python\Python312\python.exe')}; & $py.Source -c "from pathlib import Path; import json; from cayenne_runtime import redact; p=Path(r'$root')/'artifacts'/'cayenne'/'runs'/'$RunId'; [f.write_text(json.dumps(redact(json.loads(f.read_text(encoding='utf-8')),redact_emails=False),indent=2)+'\n',encoding='utf-8') for f in p.rglob('*.json')]; print('redaction validated')"
